    if not i["Request"] or i["Trip"] or not 1 <= preset <= 5:
        count = 0
    else:
        count = min(self.state.get("count", 0) + 1, preset)
    self.state["count"] = count
    return {"Ready": count >= preset if 1 <= preset <= 5 else False, "Count": count}
